const TEMPLATE="<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#F8F4EC\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23143F29'/%3E%3Ctext x='32' y='43' font-family='Georgia,serif' font-size='30' fill='%23D9BE7A' text-anchor='middle'%3ERA%3C/text%3E%3C/svg%3E\">\n<meta charset=\"utf-8\">\n<title>{{title}}</title>\n\n\n\n\n\n\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Manrope:wght@400;500;600;700&family=Tiro+Devanagari+Hindi&display=swap\">\n<style>\n:root{\n  --ivory:#F8F4EC; --ivory-2:#F1EBDF; --parchment:#E6DCC8;\n  --ink:#2B2822; --ink-soft:#6E665B;\n  --green:#1F5B3B; --green-deep:#143F29;\n  --gold:#B8923F; --gold-light:#D9BE7A; --gold-pale:#F3EAD3;\n  --plum:#5C2A4A; --navy:#1E2A4A;\n  --serif:\"Cormorant Garamond\",\"Cormorant\",Georgia,\"Times New Roman\",serif;\n  --sans:\"Manrope\",\"Helvetica Neue\",Arial,sans-serif;\n  --hindi:\"Tiro Devanagari Hindi\",\"Noto Sans Devanagari\",\"Mangal\",serif;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:var(--ivory);color:var(--ink);font-family:var(--serif);font-size:19px;line-height:1.55;-webkit-font-smoothing:antialiased;overflow-x:hidden}\nbody.intro-lock{overflow:hidden}\n.wrap{max-width:1120px;margin:0 auto;padding-inline:20px}\nh1,h2,h3{font-weight:500;margin:0;text-wrap:balance}\na{color:var(--green)}\n.eyebrow{font-family:var(--sans);font-weight:700;font-size:11px;letter-spacing:.26em;text-transform:uppercase;color:var(--gold)}\n.hindi{font-family:var(--hindi);font-weight:400}\n.line{width:56px;height:1px;background:var(--gold);margin:18px auto}\n\n/* ---------- opening sequence ---------- */\n.intro{position:fixed;inset:0;z-index:100;background:var(--ivory);display:grid;place-items:center;color:var(--green-deep);text-align:center;transition:opacity 1.8s ease,visibility 1.8s;will-change:opacity}\n.intro.out{opacity:0;visibility:hidden}\n.intro .g{width:min(56vw,300px);aspect-ratio:1;border-radius:50%;position:relative;margin:0 auto;animation:gIn 2.4s cubic-bezier(.2,.7,.2,1) both}\n.intro .g img{width:100%;height:100%;display:block}\n.intro .g::before{content:\"\";position:absolute;inset:-22%;border-radius:50%;background:radial-gradient(circle,rgba(217,190,122,.55),rgba(217,190,122,0) 62%);animation:glow 3s ease-in-out infinite;z-index:-1}\n@keyframes gIn{from{opacity:0;transform:scale(.8);filter:blur(10px)}to{opacity:1;transform:none;filter:none}}\n@keyframes glow{0%,100%{opacity:.5;transform:scale(.95)}50%{opacity:1;transform:scale(1.05)}}\n.intro .mantra{font-family:var(--hindi);font-size:clamp(20px,4vw,30px);margin:26px 0 0;letter-spacing:.04em;color:var(--green-deep);animation:tIn 1.4s 1.1s both}\n.intro .sub{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin:10px 0 0;animation:tIn 1.4s 1.9s both}\n@keyframes tIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n.intro .skip-wrap{display:inline-block;position:relative;margin:30px auto 0}\n.intro .skip{display:block;margin:0 auto;position:relative;background:var(--green-deep);border:1px solid var(--green-deep);color:var(--ivory);font-family:var(--sans);font-weight:700;font-size:clamp(12px,1.5vw,14px);letter-spacing:.18em;text-transform:uppercase;padding:18px 34px;border-radius:999px;cursor:pointer;box-shadow:0 18px 34px -20px rgba(20,63,41,.8);animation:tIn 1s 2.6s both,pulse 2.6s 3.6s ease-in-out infinite}\n.intro .skip:hover{background:var(--green)}\n.intro .skip:focus-visible{outline:2px solid var(--gold);outline-offset:4px}\n.intro .skip-hint{position:absolute;right:0;top:100%;margin-top:9px;display:flex;align-items:flex-start;gap:5px;font-family:var(--serif);font-weight:600;font-style:italic;font-size:17px;color:var(--green-deep);white-space:nowrap;pointer-events:none;animation:tIn 1s 3.1s both,nudge 1.8s 4.1s ease-in-out infinite}\n.intro .skip-hint svg{width:29px;height:29px;flex:0 0 auto;margin-top:-4px;color:var(--green-deep)}\n@keyframes nudge{0%,100%{transform:translate(0,0)}50%{transform:translate(-3px,-3px)}}\n@media (max-width:420px){.intro .skip-hint{font-size:14.5px}.intro .skip-hint svg{width:24px;height:24px}}\n@keyframes pulse{0%,100%{box-shadow:0 18px 34px -20px rgba(20,63,41,.8),0 0 0 0 rgba(184,146,63,.5)}50%{box-shadow:0 18px 34px -20px rgba(20,63,41,.8),0 0 0 14px rgba(184,146,63,0)}}\n.spark{position:absolute;width:4px;height:4px;border-radius:50%;background:var(--gold);opacity:0;animation:spark 4s linear infinite}\n@keyframes spark{0%{opacity:0;transform:translateY(0) scale(.6)}20%{opacity:.8}100%{opacity:0;transform:translateY(-140px) scale(1.2)}}\nbody.pre .reveal{opacity:0}\n.reveal{transition:opacity 2.4s ease .15s}\n.logo-wrap img{opacity:0}\nbody.gen .logo-wrap img{animation:genLogo 3.2s cubic-bezier(.22,.61,.36,1) both}\n@keyframes genLogo{0%{opacity:0;clip-path:circle(0% at 50% 50%);transform:scale(.92)}40%{opacity:1}100%{opacity:1;clip-path:circle(72% at 50% 50%);transform:scale(1)}}\nbody.gen .logo-wrap::after{content:\"\";position:absolute;inset:0;border-radius:50%;background:linear-gradient(115deg,transparent 30%,rgba(255,244,214,.75) 50%,transparent 70%);mix-blend-mode:screen;animation:shine 2s 1.3s ease-out both;pointer-events:none}\n@keyframes shine{from{transform:translateX(-120%)}to{transform:translateX(120%)}}\nbody.done .logo-wrap img{opacity:1;animation:none;transform:scale(1)}\n@media (prefers-reduced-motion:reduce){.intro .g,.intro .g::before,.intro .mantra,.intro .sub,.intro .skip,.intro .skip-hint,.spark,body.gen .logo-wrap img,body.gen .logo-wrap::after{animation:none}.logo-wrap img{opacity:1}.reveal{transition:none}body.pre .reveal{opacity:1}}\n\n/* ---------- top bar ---------- */\n.topbar{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:rgba(248,244,236,.82);backdrop-filter:blur(12px);border-bottom:1px solid rgba(184,146,63,.18)}\n@media (max-width:760px){.topbar{background:rgba(248,244,236,.96);backdrop-filter:none}}\n.topbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:10px;height:58px}\n.topbar .brand{flex:0 0 auto;font-family:var(--serif);font-size:22px;color:var(--green-deep);text-decoration:none;letter-spacing:.02em}\n.topbar .brand i{font-style:italic;color:var(--gold);margin:0 3px}\n.topbar nav{flex:1 1 auto;min-width:0;display:flex;gap:8px;font-family:var(--sans);font-size:11.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none;padding:2px;-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent 100%);mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent 100%)}\n.topbar nav::-webkit-scrollbar{display:none}\n.topbar nav a{flex:0 0 auto;text-decoration:none;color:var(--ink-soft);border:1px solid rgba(184,146,63,.42);border-radius:999px;padding:8px 14px;white-space:nowrap;transition:background .18s,color .18s,border-color .18s;display:inline-flex;align-items:center;gap:6px}\n.topbar nav a:hover{background:var(--green-deep);border-color:var(--green-deep);color:var(--ivory)}\n@media (max-width:980px){.topbar .wrap{gap:8px}.topbar nav{font-size:11px}.topbar nav a{padding:7px 11px}}\n@media (max-width:700px){.topbar .brand{display:none}}\n@media (max-width:560px){.topbar nav{gap:6px}.topbar nav a{padding:7px 10px;font-size:10.5px}.topbar .wrap{gap:8px;padding-inline:2px}}\n@media (max-width:400px){.topbar nav a{padding:6px 9px;font-size:10px}}\n.music{flex:0 0 auto;white-space:nowrap;text-decoration:none;border:1px solid rgba(184,146,63,.6);background:transparent;color:var(--green-deep);font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;padding:9px 14px;border-radius:999px;cursor:pointer;display:flex;align-items:center;gap:8px}\n.music:hover{background:var(--gold-pale)}\n.music #musicLabel{white-space:nowrap}\n@media (max-width:560px){.music{padding:8px 11px;font-size:10px;letter-spacing:.1em;gap:6px}}\n@media (max-width:400px){.music #musicLabel{display:none}.music{padding:9px;gap:0}}\n.music .bars{display:inline-flex;gap:2px;align-items:flex-end;height:12px}\n.music .bars i{display:block;width:2px;height:4px;background:var(--gold)}\n.music.on .bars i{animation:bar 1.1s ease-in-out infinite}\n.music.on .bars i:nth-child(2){animation-delay:.18s}.music.on .bars i:nth-child(3){animation-delay:.36s}\n@media (prefers-reduced-motion:reduce){.music.on .bars i{animation:none}}\n@keyframes bar{0%,100%{height:4px}50%{height:12px}}\n\n/* ---------- hero ---------- */\n.hero{position:relative;background:var(--ivory)}\n.hero-art{position:relative;height:min(58vw,640px);min-height:380px;background:url(\"/assets/1\") center bottom/cover no-repeat}\n.hero-art::before{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,var(--ivory) 0%,rgba(248,244,236,.5) 18%,rgba(248,244,236,0) 45%)}\n.hero-art::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:34%;background:linear-gradient(180deg,rgba(248,244,236,0),var(--ivory))}\n.logo-wrap{position:absolute;left:50%;top:calc(min(58vw,640px)*.12);transform:translateX(-50%);width:min(50vw,330px);aspect-ratio:1;border-radius:50%;background:#fff;border:3px solid var(--gold);outline:1px solid var(--gold-light);outline-offset:6px;box-shadow:0 0 0 12px rgba(255,255,255,.55),0 24px 50px -30px rgba(43,40,34,.5);display:grid;place-items:center;z-index:2;overflow:hidden;isolation:isolate;-webkit-mask-image:-webkit-radial-gradient(white,black);transform:translateX(-50%) translateZ(0)}\n.logo-wrap img{width:100%;height:100%;object-fit:cover;border-radius:50%;will-change:transform,opacity}\n.hero-text{position:relative;text-align:center;padding:28px 20px 0;margin-top:0}\n.hero .greet{font-family:var(--serif);font-style:italic;font-size:clamp(22px,3.2vw,30px);color:var(--green-deep);min-height:1.4em;margin:0;line-height:1.3}\n.hero .greet b{font-weight:500;font-style:normal;color:var(--gold)}\n.hero h1{font-size:clamp(50px,9vw,108px);line-height:1;color:var(--green-deep);letter-spacing:.005em;margin-top:14px}\n.hero h1 .amp{font-style:normal;color:var(--gold);font-weight:400;font-size:.62em;margin:0 .14em;position:relative;top:-.04em}\n.hero .dates{margin:26px 0 0;font-family:var(--sans);font-weight:700;letter-spacing:.22em;text-transform:uppercase;font-size:clamp(17px,2.3vw,25px);color:var(--green-deep)}\n.hero .dates span{display:inline-block;padding:0 14px;position:relative}\n.hero .dates span::before,.hero .dates span::after{content:\"\";position:absolute;top:50%;width:clamp(22px,4vw,54px);height:1px;background:linear-gradient(90deg,transparent,var(--gold));}\n.hero .dates span::before{right:100%}\n.hero .dates span::after{left:100%;background:linear-gradient(90deg,var(--gold),transparent)}\n.hero .place{margin:8px 0 0;font-style:italic;font-size:21px;color:var(--ink-soft)}\n.hash{font-family:var(--sans);font-weight:700;letter-spacing:.2em;color:var(--gold);text-transform:none}\n.hero .hash{margin:18px 0 0;font-size:clamp(17px,2.4vw,23px)}\n\n/* countdown */\n.count{display:flex;justify-content:center;align-items:center;gap:clamp(10px,2.4vw,22px);flex-wrap:wrap;padding:38px 16px 0;margin:0 auto}\n.tile{position:relative;width:clamp(72px,17vw,116px);background:#fff;border:1px solid var(--gold-light);border-radius:10px;padding:34px 6px 14px;text-align:center;box-shadow:0 18px 30px -22px rgba(43,40,34,.45)}\n.tile::before{content:\"\";position:absolute;left:14px;right:14px;top:-5px;height:10px;border-radius:5px;background:linear-gradient(90deg,var(--gold),var(--gold-light))}\n.tile .tab{position:absolute;left:0;right:0;top:10px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.24em;text-transform:uppercase;color:var(--gold)}\n.tile b{display:block;font-weight:600;font-size:clamp(36px,6vw,56px);line-height:1;color:var(--green-deep);font-variant-numeric:tabular-nums}\n.hourglass{width:40px;height:56px;animation:flip 8s ease-in-out infinite;transform-origin:center}\n.hourglass .sandTop{transform-origin:20px 22px;animation:drain 8s linear infinite}\n.hourglass .sandBot{transform-origin:20px 50px;animation:fill 8s linear infinite}\n@keyframes flip{0%,88%{transform:rotate(0)}100%{transform:rotate(180deg)}}\n@keyframes drain{0%{transform:scaleY(1)}85%{transform:scaleY(.08)}100%{transform:scaleY(.08)}}\n@keyframes fill{0%{transform:scaleY(.08)}85%{transform:scaleY(1)}100%{transform:scaleY(1)}}\n@media (prefers-reduced-motion:reduce){.hourglass,.hourglass .sandTop,.hourglass .sandBot{animation:none}}\n@media (max-width:480px){.hourglass{display:none}}\n\n/* ---------- sections ---------- */\nsection{padding-block:80px}\n.sec-head{text-align:center;margin-bottom:44px}\n.sec-head h2{font-size:clamp(36px,5vw,56px);color:var(--green-deep)}\n.sec-head .eyebrow{display:block;margin-bottom:10px}\n.sec-head p{max-width:58ch;margin:14px auto 0;color:var(--ink-soft);font-style:italic}\n\n/* celebration timeline */\n.timeline{position:relative;max-width:980px;margin:0 auto;padding:10px 0 20px}\n.timeline::before{content:\"\";position:absolute;left:50%;top:0;bottom:0;width:2px;background:linear-gradient(180deg,transparent,var(--gold-light) 6%,var(--gold-light) 94%,transparent);transform:translateX(-50%)}\n.tl-day{position:relative;text-align:center;margin:26px 0 34px;z-index:1}\n.tl-day span{display:inline-block;background:var(--green-deep);color:var(--ivory);font-family:var(--sans);font-weight:700;font-size:11px;letter-spacing:.24em;text-transform:uppercase;padding:12px 22px;border-radius:999px;box-shadow:0 12px 30px -16px rgba(20,63,41,.7)}\n.contacts{margin-top:10px}\n.contact-cols{display:flex;flex-wrap:wrap;justify-content:center;gap:12px 64px;margin-top:10px}\n.contact-cols>div{min-width:190px}\n.contact-cols .tab{display:block;font-family:var(--sans);font-weight:600;font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold-light);margin-bottom:6px}\n.contact-cols .sub{margin:0;line-height:1.75}\n.tl-foot{text-align:center;font-style:italic;color:var(--ink-soft);font-size:clamp(17px,2vw,20px);margin:22px auto 0;max-width:980px}\n.tl-item{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:0 64px;margin-bottom:34px;align-items:center}\n.tl-item::before{content:\"\";position:absolute;left:50%;top:50%;width:14px;height:14px;border-radius:50%;background:#fff;border:3px solid var(--ev-accent,var(--gold));transform:translate(-50%,-50%);z-index:2;box-shadow:0 0 0 6px var(--ivory)}\n.tl-time{text-align:right;color:var(--green-deep);font-family:var(--serif)}\n.tl-time b{font-weight:500;font-size:clamp(40px,5.5vw,64px);line-height:1;letter-spacing:-.01em}\n.tl-time small{display:block;font-family:var(--sans);font-weight:700;font-size:11px;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin-top:6px}\n.tl-card{position:relative;background:var(--ev-bg,#fff);border-radius:14px;padding:26px 28px;box-shadow:0 26px 50px -36px rgba(43,40,34,.5);border:1px solid rgba(184,146,63,.18)}\n.tl-card::after{content:\"\";position:absolute;left:-9px;top:50%;width:16px;height:16px;background:inherit;border-left:1px solid rgba(184,146,63,.18);border-bottom:1px solid rgba(184,146,63,.18);transform:translateY(-50%) rotate(45deg)}\n.tl-item:nth-child(odd of .tl-item){grid-template-areas:\"card time\"}\n.tl-item:nth-child(even of .tl-item){grid-template-areas:\"time card\"}\n.tl-item:nth-child(odd of .tl-item) .tl-card{grid-area:card}\n.tl-item:nth-child(odd of .tl-item) .tl-time{grid-area:time;text-align:left}\n.tl-item:nth-child(odd of .tl-item) .tl-card::after{left:auto;right:-9px;border-left:0;border-bottom:0;border-right:1px solid rgba(184,146,63,.18);border-top:1px solid rgba(184,146,63,.18)}\n.tl-tag{display:inline-block;font-family:var(--sans);font-weight:700;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--ev-accent,var(--gold));margin-bottom:8px}\n.tl-card h4{margin:0;font-size:32px;font-weight:500;line-height:1.05;color:var(--ink)}\n.tl-card .vibe{margin:10px 0 14px;font-style:italic;color:var(--ink-soft);font-size:18px}\n.dress{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;font-size:16px;line-height:1.4;align-items:baseline}\n.dress span{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-soft)}\n.dress em{font-style:normal;color:var(--ink)}\n.swatch{display:flex;gap:6px;margin-top:16px}\n.swatch i{width:16px;height:16px;border-radius:50%;border:1px solid rgba(0,0,0,.08)}\n.tl-item.dark .tl-card h4,.tl-item.dark .dress em{color:var(--ivory)}\n.tl-item.dark .tl-card .vibe{color:#CFC3DE}\n.tl-item.dark .dress span{color:#CFC3DE}\n@media (max-width:760px){\n  .timeline::before{left:18px;transform:none}\n  .tl-day{text-align:left;padding-left:46px}\n  .tl-item,.tl-item:nth-child(odd of .tl-item),.tl-item:nth-child(even of .tl-item){grid-template-columns:1fr;grid-template-areas:\"time\" \"card\";gap:10px;padding-left:46px}\n  .tl-item::before{left:18px;top:22px;transform:translate(-50%,0)}\n  .tl-time,.tl-item:nth-child(odd of .tl-item) .tl-time{text-align:left;display:flex;align-items:baseline;gap:10px}\n  .tl-time b{font-size:34px}.tl-time small{margin:0}\n  .tl-card::after,.tl-item:nth-child(odd of .tl-item) .tl-card::after{display:none}\n  .tl-card{padding:22px 20px}\n}\n\n/* road with the wedding chariot \u2014 the strip is always tall enough to show the whole chariot */\n.road{--cw:min(520px,72vw);position:relative;height:calc(var(--cw)/2.007 + 56px);overflow:hidden;background:var(--ivory);margin-top:10px}\n.road::after{content:\"\";position:absolute;left:0;right:0;bottom:30px;height:1px;background:repeating-linear-gradient(90deg,var(--gold) 0 14px,transparent 14px 26px);opacity:.6}\n.cart{position:absolute;bottom:26px;left:calc(-1 * var(--cw) - 40px);width:var(--cw);animation:ride 36s linear infinite;will-change:transform}\n.cart img{display:block;width:100%;height:auto;animation:bob 1.15s ease-in-out infinite;filter:drop-shadow(0 10px 12px rgba(43,40,34,.14))}\n@keyframes ride{from{transform:translateX(0)}to{transform:translateX(calc(100vw + var(--cw) + 80px))}}\n@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}\n@media (prefers-reduced-motion:reduce){.cart,.cart img{animation:none!important}.cart{position:relative;left:auto;bottom:auto;margin:14px auto 0}}\n\n/* venue + travel */\n.venue{background:var(--ivory-2)}\n.venue-scene{position:relative;width:100%;aspect-ratio:2000/1068;background:url(\"/assets/2\") center/cover no-repeat}\n.venue-scene::before{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,var(--ivory-2) 0%,rgba(241,235,223,0) 14%)}\n.venue-info{text-align:center;padding:64px 20px 28px;max-width:720px;margin:0 auto}\n.venue .name{font-size:clamp(36px,5vw,56px);color:var(--green-deep)}\n.venue .addr{color:var(--ink-soft);margin:8px 0 18px;font-style:italic;font-size:19px}\n.guide{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;margin-top:44px}\n.tip{padding:24px 24px 22px;background:var(--ivory);border-radius:8px;border:1px solid rgba(184,146,63,.25);position:relative}\n.tip .ico{display:block;width:44px;height:44px;margin-bottom:12px}\n.tip .ico svg{width:100%;height:100%;fill:none;stroke:var(--gold);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.tip b{display:block;font-family:var(--sans);font-weight:700;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--gold);margin-bottom:10px}\n.tip p{margin:0;font-size:17px;color:var(--ink)}\n.tip p+p{margin-top:8px}\n.tip .big{font-size:24px;line-height:1.2;margin-bottom:6px}\n.tip-note{background:var(--gold-pale);border-color:rgba(184,146,63,.5)}\n.postcard{margin:40px auto 0;max-width:420px}\n.postcard img{width:100%;height:auto;display:block;border-radius:10px;transform:rotate(-2deg);box-shadow:0 20px 40px -24px rgba(43,40,34,.45)}\n.postcard figcaption{font-family:var(--sans);font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink-soft);margin-top:14px;text-align:center}\n.btn{display:inline-flex;align-items:center;gap:10px;padding:14px 24px;border:1px solid var(--green);color:var(--green-deep);background:transparent;font-family:var(--sans);font-weight:700;font-size:11px;letter-spacing:.2em;text-transform:uppercase;text-decoration:none;cursor:pointer;border-radius:999px;transition:background .2s,color .2s}\n.btn:hover{background:var(--green);color:var(--ivory)}\n.btn.solid{background:var(--green);color:var(--ivory)}\n.btn.solid:hover{background:var(--green-deep)}\n.btn svg{width:16px;height:16px;fill:currentColor}\n\n/* rsvp */\n.rsvp .card{max-width:880px;margin:0 auto;background:#fff;border-radius:12px;padding:52px 48px;font-size:20px;box-shadow:0 30px 60px -40px rgba(43,40,34,.3)}\n@media (max-width:480px){.rsvp .card{padding:28px 18px}}\n.field{display:grid;gap:8px;margin-bottom:22px}\n.field>label,legend{font-family:var(--sans);font-weight:700;font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-soft)}\ninput[type=text],input[type=tel],input[type=number],input[type=date],textarea,select{width:100%;font:inherit;font-size:20px;padding:15px 16px;border:1px solid var(--parchment);background:var(--ivory);color:var(--ink);border-radius:6px}\ninput:focus,textarea:focus,select:focus{outline:2px solid var(--gold);outline-offset:1px;border-color:var(--gold)}\ntextarea{min-height:110px;resize:vertical}\nfieldset{border:0;padding:0;margin:0 0 22px}\n.choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.choice{display:flex;gap:12px;align-items:center;padding:15px 16px;border:1px solid var(--parchment);background:var(--ivory);cursor:pointer;font-size:18px;border-radius:6px}\n.choice input{accent-color:var(--green);width:18px;height:18px;min-width:18px;min-height:18px;flex:0 0 18px;margin:0}\n.choice:has(input:checked){border-color:var(--green);background:#EEF4EE}\n.choice-text{display:flex;flex-direction:column;gap:3px}\n.choice .ev-when{font-size:13px;font-weight:400;color:var(--ink-soft)}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n@media (max-width:480px){.two{grid-template-columns:1fr}}\n.note{font-size:15px;color:var(--ink-soft);font-style:italic;margin-top:16px}\n.decline-note{padding:18px;border:1px dashed var(--gold);background:var(--gold-pale);margin-bottom:22px;border-radius:6px}\n\n/* social */\n.social{background:var(--ivory-2)}\n.posts{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;align-items:start}\n@media (max-width:900px){.posts{grid-template-columns:repeat(3,1fr)}}\n@media (max-width:600px){.posts{grid-template-columns:repeat(2,1fr);gap:14px}}\n.dl{margin-top:10px;font-family:var(--sans);font-weight:700;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--green-deep);background:transparent;border:1px solid var(--gold-light);border-radius:999px;padding:8px 14px;cursor:pointer}\n.dl:hover{background:var(--gold-pale)}\n.dl[disabled]{opacity:.45;cursor:default}\n.post{background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 20px 40px -30px rgba(43,40,34,.4)}\n.post img,.post video{width:100%;height:auto;display:block;aspect-ratio:9/16;object-fit:cover;background:#000}\n.post .cap{padding:14px 16px 16px}\n.post .cap b{display:block;font-family:var(--sans);font-weight:700;font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:4px}\n.post .cap span{display:block;font-size:16px;color:var(--ink-soft);font-style:italic}\n.post.soon{border:1px dashed var(--gold-light);background:var(--ivory);box-shadow:none}\n.post.soon .ph{aspect-ratio:9/16;display:grid;place-items:center;text-align:center;padding:20px;color:var(--gold)}\n.post.soon .ph b{display:block;font-size:44px;line-height:1;color:var(--green-deep);font-weight:500}\n.post.soon .ph small{font-family:var(--sans);font-size:10px;letter-spacing:.24em;text-transform:uppercase;font-weight:700}\n.story-grid{display:grid;grid-template-columns:minmax(260px,380px) 1fr;gap:48px;align-items:center;margin-top:60px;padding-top:60px;border-top:1px solid var(--gold-light)}\n@media (max-width:820px){.story-grid{grid-template-columns:1fr;gap:28px}}\n.story-grid img{width:100%;height:auto;display:block;border-radius:200px 200px 6px 6px;box-shadow:0 30px 60px -30px rgba(43,40,34,.35)}\n.story h2{font-size:clamp(36px,5vw,56px);color:var(--green-deep);line-height:1.05}\n.story h2 em{font-style:italic;color:var(--gold);font-weight:400}\n.story p{max-width:48ch;margin:18px auto 0}\n.story .quote{font-style:italic;color:var(--ink-soft);border-top:1px solid var(--gold-light);padding-top:16px;margin-top:24px;font-size:18px}\n\n/* photos QR */\n.photos .qr{display:grid;grid-template-columns:auto 1fr;gap:40px;align-items:center;max-width:840px;margin:0 auto;background:#fff;border-radius:14px;padding:32px;box-shadow:0 30px 60px -40px rgba(43,40,34,.35)}\n@media (max-width:640px){.photos .qr{grid-template-columns:1fr;text-align:center}}\n.photos .qr img{width:220px;max-width:100%;height:auto;border-radius:10px;border:1px solid var(--parchment);margin:0 auto;display:block}\n.photos .qr h3{font-size:30px;color:var(--green-deep)}\n.photos .qr p{margin:10px 0 0;color:var(--ink-soft)}\n.photos .qr .pill{display:inline-block;margin-top:14px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);border:1px dashed var(--gold-light);padding:6px 12px;border-radius:999px}\n\n/* wishes */\n.wishes{background:var(--ivory-2)}\n.wishes .card{max-width:640px;margin:0 auto;background:#fff;border-radius:10px;padding:36px 32px;box-shadow:0 30px 60px -40px rgba(43,40,34,.3)}\n@media (max-width:480px){.wishes .card{padding:26px 18px}}\n\n/* footer */\nfooter{padding:70px 20px 80px;text-align:center;background:var(--green-deep);color:var(--ivory)}\nfooter .flogo{width:150px;height:150px;border-radius:50%;background:#fff;border:3px solid var(--gold);outline:1px solid var(--gold-light);outline-offset:5px;margin:0 auto 26px;display:grid;place-items:center;overflow:hidden;isolation:isolate;-webkit-mask-image:-webkit-radial-gradient(white,black)}\nfooter .flogo img{width:100%;height:100%;object-fit:cover;border-radius:50%}\nfooter .tag{font-family:var(--sans);font-weight:700;letter-spacing:.2em;font-size:18px;color:var(--gold-light)}\nfooter .lines{font-size:clamp(24px,3.4vw,34px);font-style:italic;line-height:1.3;max-width:26ch;margin:18px auto 0;color:var(--ivory)}\nfooter p.sub{margin:16px auto 0;max-width:52ch;color:rgba(248,244,236,.8);font-style:italic}\nfooter .names{font-size:36px;margin-top:26px}\nfooter .names .hindi{display:block;font-size:16px;color:var(--gold-light);margin-top:6px}\n.share{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:28px}\n.share .btn{border-color:rgba(217,190,122,.7);color:var(--ivory)}\n.share .btn:hover{background:var(--gold);color:var(--green-deep)}\n.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--green-deep);color:var(--ivory);padding:12px 20px;border-radius:999px;font-size:16px;opacity:0;pointer-events:none;transition:opacity .3s;z-index:50}\n.toast.show{opacity:1}\n</style>\n</head>\n<body>\n<div class=\"intro\" id=\"intro\" aria-label=\"Opening blessing\">\n  <span class=\"spark\" style=\"left:30%;top:60%;animation-delay:.2s\"></span>\n  <span class=\"spark\" style=\"left:44%;top:70%;animation-delay:1.1s\"></span>\n  <span class=\"spark\" style=\"left:58%;top:64%;animation-delay:2s\"></span>\n  <span class=\"spark\" style=\"left:68%;top:56%;animation-delay:.7s\"></span>\n  <span class=\"spark\" style=\"left:36%;top:48%;animation-delay:2.6s\"></span>\n  <div>\n    <div class=\"g\"><img src=\"/assets/3\" alt=\"Lord Ganesha\" width=\"300\" height=\"300\"></div>\n    <p class=\"mantra\">|| \u0936\u094d\u0930\u0940 \u0917\u0923\u0947\u0936\u093e\u092f \u0928\u092e\u0903 ||</p>\n    <p class=\"sub\">{{intro}}</p>\n    <div class=\"skip-wrap\">\n      <button class=\"skip\" type=\"button\" id=\"skipIntro\">Let the celebrations begin</button>\n      <span class=\"skip-hint\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M34 32C23 31 13 24 9 11\"/><path d=\"M5 17L9 9L17 13\"/></svg>Click here</span>\n    </div>\n  </div>\n</div>\n\n<div class=\"topbar reveal\">\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\">R<i>&amp;</i>A</a>\n    <nav>\n      <a href=\"#events\">Celebrations</a>\n      <a href=\"#venue\">Venue</a>\n      \n      \n      \n      \n      \n    </nav>\n    <button class=\"music\" id=\"musicBtn\" type=\"button\" aria-pressed=\"false\" title=\"Sunehra \u2014 Jai Dhir & Lost Stories\">\n      <span class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></span><span id=\"musicLabel\">Play our song</span>\n    </button>\n    <audio id=\"song\" preload=\"none\" loop><source src=\"/assets/4\" type=\"audio/mpeg\"></audio>\n  </div>\n</div>\n\n<header class=\"hero\" id=\"top\">\n  <div class=\"hero-art reveal\"></div>\n  <div class=\"logo-wrap\"><img src=\"/assets/logo\" alt=\"A and R monogram with peacock and lotus\" width=\"330\" height=\"330\"></div>\n  <div class=\"hero-text wrap reveal\">\n    <p class=\"greet\" id=\"greet\">You are warmly invited to the wedding of</p>\n    <h1>{{names}}</h1>\n    <p class=\"dates\"><span>{{dates}}</span></p>\n    <p class=\"place\">{{place}}</p>\n    <p class=\"hash\" style=\"font-size:12px\">Wedding \u00b7 {{weddingLabel}}</p>\n  </div>\n  <div class=\"count reveal\" id=\"count\" aria-label=\"Countdown to the wedding\">\n    <div class=\"hourglass\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 40 56\" width=\"40\" height=\"56\"><path d=\"M6 3h28M6 53h28M9 3v6c0 8 11 11 11 19s-11 11-11 19v6M31 3v6c0 8-11 11-11 19s11 11 11 19v6\" fill=\"none\" stroke=\"#B8923F\" stroke-width=\"2\" stroke-linecap=\"round\"/><path class=\"sandTop\" d=\"M13 9c0 5 7 8 7 13 0-5 7-8 7-13Z\" fill=\"#E9A93C\"/><path class=\"sandBot\" d=\"M12 50c0-6 8-9 8-13 0 4 8 7 8 13Z\" fill=\"#E9A93C\"/></svg>\n    </div>\n    <div class=\"tile\"><span class=\"tab\">Days</span><b id=\"cd-d\">\u2014</b></div>\n    <div class=\"tile\"><span class=\"tab\">Hours</span><b id=\"cd-h\">\u2014</b></div>\n    <div class=\"tile\"><span class=\"tab\">Minutes</span><b id=\"cd-m\">\u2014</b></div>\n    <div class=\"tile\"><span class=\"tab\">Seconds</span><b id=\"cd-s\">\u2014</b></div>\n  </div>\n</header>\n\n<div class=\"road\" aria-hidden=\"true\">\n  <div class=\"cart\"><img src=\"/assets/5\" alt=\"\" draggable=\"false\"></div>\n</div>\n\n<section id=\"events\" style=\"scroll-margin-top:80px\"><div class=\"wrap\"><div class=\"sec-head\"><span class=\"eyebrow\">Our celebrations</span><h2>Two days, a lifetime of memories</h2><p>Join us as we celebrate the wedding of {{couple}}.</p></div><div class=\"timeline\">{{events}}</div></div></section><section class=\"venue\" id=\"venue\" style=\"scroll-margin-top:80px\"><div class=\"venue-info\"><p class=\"eyebrow\">The venue</p><h2 class=\"name\">{{venue}}</h2><p class=\"addr\">{{address}}</p><a class=\"btn solid\" href=\"{{map}}\" target=\"_blank\" rel=\"noopener\">Open in Google Maps \u2197</a></div><div class=\"venue-scene\" role=\"img\" aria-label=\"Illustrated garden with two peacocks, chhatris and a lotus pond\"></div></section><footer><div class=\"flogo\"><img src=\"/assets/logo\" alt=\"Apeksha and Rohan monogram\" style=\"object-fit:cover;width:150px;height:150px;border-radius:50%\"></div><p class=\"lines\">Together with our families,<br>we can\u2019t wait to celebrate with you.</p><p class=\"names\">{{couple}}</p><p class=\"sub\">{{dates}} \u00b7 {{venue}}</p></footer><script>\nconst intro=document.getElementById('intro');document.body.classList.add('intro-lock','pre');function enter(){intro.classList.add('out');document.body.classList.remove('intro-lock','pre');document.body.classList.add('done')}document.getElementById('skipIntro').onclick=enter;setTimeout(enter,8000);\nconst song=document.getElementById('song'),btn=document.getElementById('musicBtn');btn.onclick=async()=>{if(song.paused){try{await song.play()}catch{document.getElementById('musicLabel').textContent='Try again';return}}else song.pause();btn.classList.toggle('on',!song.paused);btn.setAttribute('aria-pressed',String(!song.paused));document.getElementById('musicLabel').textContent=song.paused?'Play our song':'Pause song'};\nfunction tick(){let n=Math.max(0,Math.floor((new Date('{{countdown}}')-Date.now())/1000));for(const [id,k] of [['d',86400],['h',3600],['m',60],['s',1]]){document.getElementById('cd-'+id).textContent=String(Math.floor(n/k)).padStart(2,'0');n%=k}}tick();setInterval(tick,1000);\n</script></body></html>";
const ASSETS={"1": {"type": "image/jpeg", "data": ""}, "2": {"type": "image/jpeg", "data": ""}, "3": {"type": "image/png", "data": ""}, "4": {"type": "audio/mpeg", "data": ""}, "5": {"type": "image/png", "data": ""}, "logo": {"type": "image/jpeg", "data": ""}};
const DEFAULTS={"groom": "Rohan", "bride": "Apeksha", "dates": "26 & 27 December 2026", "weddingLabel": "27 December 2026", "countdown": "2026-12-27T11:00:00+05:30", "venue": "Kenisha Resort Residences", "address": "Khopoli-Pali Road, Pawasalawadi, Jambhulpada, Maharashtra 410205", "map": "https://maps.app.goo.gl/uhcZeNjyihEhkUGp7?g_st=iw", "days": [{"title": "Saturday, 26 December 2026", "attire": "", "events": [{"time": "3:30", "period": "pm", "title": "Arrival & poolside high tea", "attire": ""}, {"time": "4:00", "period": "pm", "title": "Tel Bukhi for Apeksha & Rohan", "attire": ""}, {"time": "5:00", "period": "pm", "title": "Haldi ceremony", "attire": "Traditional attire in shades of yellow"}, {"time": "7:00", "period": "pm", "title": "Cocktail & DJ night", "attire": "Casual evening wear paired with your favourite sports team jersey"}]}, {"title": "Sunday, 27 December 2026", "attire": "Festive Indian attire in pastel colours", "events": [{"time": "7:00", "period": "am", "title": "Apeksha\u2019s Chuda ceremony", "attire": ""}, {"time": "8:00", "period": "am", "title": "Apeksha\u2019s Punyavachan", "attire": ""}, {"time": "9:00", "period": "am", "title": "Rohan\u2019s Punyavachan", "attire": ""}, {"time": "11:00", "period": "am", "title": "Varmala & vows \u00b7 Phere", "attire": ""}, {"time": "12:30", "period": "pm", "title": "Lunch", "attire": ""}]}]};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(d){const couple=d.groom+' & '+d.bride;const v={title:couple+' · Wedding invitation',intro:couple+' · '+d.dates,couple,dates:d.dates,place:d.venue+', Jambhulpada, Maharashtra',weddingLabel:d.weddingLabel,venue:d.venue,address:d.address,map:d.map,countdown:d.countdown};Object.keys(v).forEach(k=>v[k]=esc(v[k]));v.names=esc(d.groom)+' <span class="amp">&amp;</span> '+esc(d.bride);v.events=d.days.map(day=>'<div class="tl-day"><span>'+esc(day.title)+'</span></div>'+(day.attire?'<p style="text-align:center;color:var(--green);margin:0 0 28px">'+esc(day.attire)+'</p>':'')+day.events.map((e,i)=>'<article class="tl-item" style="--ev-accent:#B8923F;--ev-bg:'+(i%2?'#F1EBDF':'#F7EFDC')+'"><div class="tl-time"><b>'+esc(e.time)+'</b><small>'+esc(e.period)+'</small></div><div class="tl-card"><h4>'+esc(e.title)+'</h4>'+(e.attire?'<p class="vibe">'+esc(e.attire)+'</p>':'')+'</div></article>').join('')).join('');return TEMPLATE.replace(/\{\{(\w+)\}\}/g,(_,k)=>v[k]||'')}
const ADMIN=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invitation studio</title><style>*{box-sizing:border-box}body{margin:0;background:#f8f4ec;color:#143f29;font:16px system-ui}main{max-width:840px;margin:50px auto;padding:24px}h1{font:44px Georgia;margin:15px 0}h2{font:28px Georgia}p{line-height:1.6;color:#6e665b}label{display:block;margin:18px 0 6px;font-size:13px}input{width:100%;padding:12px;border:1px solid #d4c7ac;border-radius:6px;background:#fff;font:inherit}button,.link{display:inline-block;border:0;border-radius:30px;background:#143f29;color:white;padding:13px 22px;font:inherit;cursor:pointer;margin:12px 8px 0 0;text-decoration:none}.secondary{background:#e6dcc8;color:#143f29}.panel{background:white;padding:24px;border:1px solid #e6dcc8;border-radius:12px;margin:24px 0}.row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.event{border-top:1px solid #e6dcc8;margin-top:24px;padding-top:5px}#status{position:sticky;top:0;background:#f8f4ec;padding:12px;z-index:1;white-space:pre-wrap}[hidden]{display:none!important}@media(max-width:550px){.row{grid-template-columns:1fr}main{margin:15px auto;padding:18px}h1{font-size:36px}}</style><main><a href="/" style="color:inherit">← View invitation</a><p>ROHAN & APEKSHA</p><h1>Invitation studio</h1><p>Edit the details, save, and your invitation updates for every guest.</p><div id="status" role="status" aria-live="polite"></div><form id="auth" class="panel"><h2 id="authTitle">Admin sign in</h2><p id="hint"></p><a id="ownerVerify" href="/signin-with-chatgpt?return_to=%2Fadmin" target="_top" hidden style="color:#143f29">Verify site ownership to create the first login</a><label for="username">Username</label><input id="username" autocomplete="username" required value="admin"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required><button id="authBtn">Sign in</button></form><form id="editor" hidden><div id="fields"></div><button>Save changes</button><a class="link secondary" href="/" target="_blank">View invitation ↗</a><button class="secondary" type="button" id="logout">Sign out</button></form><form id="credentials" class="panel" hidden><h2>Change admin password</h2><label for="current">Current password</label><input id="current" type="password" autocomplete="current-password" required><label for="next">New password · at least 12 characters</label><input id="next" type="password" autocomplete="new-password" minlength="12" required><button>Update password</button></form></main><script>
let data,setup=false;const $=id=>document.getElementById(id);async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x}function message(t){$('status').textContent=t}function field(parent,label,value,change,type='text'){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.type=type;input.value=value||'';input.maxLength=1000;input.addEventListener('input',()=>change(input.value));l.append(input);parent.append(l)}function draw(){const f=$('fields');f.replaceChildren();const p=document.createElement('section');p.className='panel';f.append(p);for(const [key,label] of Object.entries({groom:'Groom’s name',bride:'Bride’s name',dates:'Celebration dates',weddingLabel:'Wedding date',countdown:'Countdown date & time (include +05:30 for India)',venue:'Venue name',address:'Full address',map:'Google Maps link'}))field(p,label,data[key],v=>data[key]=v);data.days.forEach((day,di)=>{const box=document.createElement('section');box.className='panel';f.append(box);field(box,'Day heading',day.title,v=>day.title=v);field(box,'Dress code for this day',day.attire,v=>day.attire=v);day.events.forEach((e,ei)=>{const row=document.createElement('div');row.className='event';box.append(row);for(const [key,label] of Object.entries({title:'Celebration',time:'Time (e.g. 3:30)',period:'am / pm',attire:'Dress code / note'}))field(row,label,e[key],v=>e[key]=v);const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Remove celebration';remove.onclick=()=>{day.events.splice(ei,1);draw()};row.append(remove)});const add=document.createElement('button');add.type='button';add.className='secondary';add.textContent='+ Add celebration';add.onclick=()=>{day.events.push({title:'New celebration',time:'12:00',period:'pm',attire:''});draw()};box.append(add)})}async function load(){const s=await api('status');setup=s.setup;$('authTitle').textContent=setup?'Create your admin login':'Admin sign in';$('hint').textContent=setup?'Choose your own username and a password of at least 12 characters. Verify site ownership once using the link below. After setup, use only your username and password.':'';$('ownerVerify').hidden=!setup;$('authBtn').textContent=setup?'Create admin login':'Sign in';$('password').minLength=setup?12:1;if(s.authenticated){data=await api('content');draw();$('auth').hidden=true;$('editor').hidden=false;$('credentials').hidden=false}else{$('auth').hidden=false;$('editor').hidden=true;$('credentials').hidden=true}}$('auth').onsubmit=async e=>{e.preventDefault();try{await api(setup?'setup':'login',{username:$('username').value,password:$('password').value});if(setup)await api('login',{username:$('username').value,password:$('password').value});$('password').value='';message('Signed in.');await load()}catch(e){message(e.message)}};$('editor').onsubmit=async e=>{e.preventDefault();try{await api('content',data);message('Saved. Your invitation is now updated.')}catch(e){message(e.message)}};$('logout').onclick=async()=>{await api('logout',{});await load();message('Signed out.')};$('credentials').onsubmit=async e=>{e.preventDefault();try{await api('password',{current:$('current').value,password:$('next').value});$('credentials').reset();await load();message('Password updated. Sign in with your new password.')}catch(e){message(e.message)}};load().catch(e=>message(e.message));window.addEventListener('beforeunload',e=>{if(window.dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('input',e=>{if(e.target.closest('#editor'))window.dirty=true});$('editor').addEventListener('submit',()=>window.dirty=false);
</script></html>`;
const json=(v,status=200,extra={})=>new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store',...extra}});
const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
const random=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
async function digest(x){return hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x)))}
async function hash(p,s){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(s),iterations:100000,hash:'SHA-256'},key,256))}
function equal(a,b){if(a.length!==b.length)return false;let n=0;for(let i=0;i<a.length;i++)n|=a.charCodeAt(i)^b.charCodeAt(i);return n===0}
async function read(env,key){const x=await env.BUCKET.get(key);return x?x.json():null}async function put(env,key,v){await env.BUCKET.put(key,JSON.stringify(v))}
const cookie=t=>'wedding_session='+t+'; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=28800';
async function session(request,env,auth){const token=(request.headers.get('Cookie')||'').match(/(?:^|; )wedding_session=([a-f0-9]{64})/)?.[1];if(!token||!auth)return false;const s=await read(env,'session/'+await digest(token));return s&&s.expires>Date.now()&&s.version===auth.version}
function valid(d){if(!d||typeof d!=='object')return false;for(const k of ['groom','bride','dates','weddingLabel','countdown','venue','address','map'])if(typeof d[k]!=='string'||!d[k].trim()||d[k].length>1000)return false;if(!/^https:\/\//.test(d.map)||Number.isNaN(Date.parse(d.countdown)))return false;if(!Array.isArray(d.days)||d.days.length!==2)return false;return d.days.every(x=>typeof x.title==='string'&&x.title.length<1000&&typeof x.attire==='string'&&x.attire.length<1000&&Array.isArray(x.events)&&x.events.length<=30&&x.events.every(e=>['time','period','title','attire'].every(k=>typeof e[k]==='string'&&e[k].length<1000)&&/^(1[0-2]|[1-9]):[0-5]\d$/.test(e.time)&&/^(am|pm)$/.test(e.period)))}
export default {async fetch(request,env){try{const u=new URL(request.url),path=u.pathname;if(path.startsWith('/assets/')){const a=ASSETS[path.slice(8)];if(!a)return new Response('Not found',{status:404});const bytes=Uint8Array.from(atob(a.data),c=>c.charCodeAt(0));return new Response(bytes,{headers:{'Content-Type':a.type,'Cache-Control':'public,max-age=86400'}})}if(path==='/admin'||path==='/admin/')return new Response(ADMIN,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Frame-Options':'DENY'}});if(path.startsWith('/api/')){if(!env.BUCKET)return json({error:'Storage is not configured.'},503);const savedAuth=await read(env,'auth'),bootstrap=env.ADMIN_BOOTSTRAP_AUTH?JSON.parse(env.ADMIN_BOOTSTRAP_AUTH):null;const auth=bootstrap&&savedAuth?.bootstrapVersion!==bootstrap.version?{...bootstrap,bootstrapVersion:bootstrap.version}:savedAuth;const logged=await session(request,env,auth);if(path==='/api/status')return json({setup:!auth,authenticated:!!logged});if(request.method==='POST'&&request.headers.get('Origin')!==u.origin)return json({error:'Invalid origin.'},403);if(path==='/api/content'&&request.method==='GET')return logged?json(await read(env,'content')||DEFAULTS):json({error:'Sign in required.'},401);if(request.method!=='POST')return json({error:'Not found.'},404);const raw=await request.text();if(raw.length>100000)return json({error:'Request too large.'},413);const b=JSON.parse(raw);if(path==='/api/setup'||path==='/api/login'){if(path.endsWith('setup')){if(auth)return json({error:'Admin is already configured.'},409);if(!env.ADMIN_OWNER_EMAIL || !request.headers.get('oai-authenticated-user-id') || request.headers.get('oai-authenticated-user-email')?.toLowerCase()!==env.ADMIN_OWNER_EMAIL.toLowerCase())return json({error:'Only the site owner can create the first admin login. Use the owner verification link above.'},403);if(typeof b.password!=='string'||b.password.length<12||b.password.length>256||! /^[a-zA-Z0-9_.-]{3,40}$/.test(b.username))return json({error:'Use a 3–40 character username and a password of 12–256 characters.'},400);const salt=random();await put(env,'auth',{username:b.username,salt,hash:await hash(b.password,salt),version:random()});return json({ok:true})}if(!auth)return json({error:'Set up your admin login first.'},409);const ip=request.headers.get('CF-Connecting-IP')||'unknown',key='attempt/'+await digest(ip);const limit=await read(env,key);if(limit&&limit.until>Date.now()&&limit.count>=8)return json({error:'Too many attempts. Try again in 15 minutes.'},429);const matches=typeof b.password==='string'&&b.password.length<=256&&equal(await hash(b.password,auth.salt),auth.hash)&&b.username===auth.username;if(!matches){await put(env,key,{count:limit&&limit.until>Date.now()?limit.count+1:1,until:limit&&limit.until>Date.now()?limit.until:Date.now()+900000});return json({error:'Incorrect username or password.'},401)}await env.BUCKET.delete(key);const token=random();await put(env,'session/'+await digest(token),{version:auth.version,expires:Date.now()+28800000});return json({ok:true},200,{'Set-Cookie':cookie(token)})}if(!logged)return json({error:'Sign in required.'},401);if(path==='/api/content'){if(!valid(b))return json({error:'Check all fields, times, map URL and countdown date.'},400);await put(env,'content',b);return json({ok:true})}if(path==='/api/logout')return json({ok:true},200,{'Set-Cookie':'wedding_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0'});if(path==='/api/password'){if(typeof b.current!=='string'||!equal(await hash(b.current,auth.salt),auth.hash))return json({error:'Current password is incorrect.'},403);if(typeof b.password!=='string'||b.password.length<12||b.password.length>256)return json({error:'Use 12–256 characters.'},400);const salt=random();await put(env,'auth',{username:auth.username,salt,hash:await hash(b.password,salt),version:random(),...(auth.bootstrapVersion?{bootstrapVersion:auth.bootstrapVersion}:{})});return json({ok:true},200,{'Set-Cookie':'wedding_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0'})}return json({error:'Not found.'},404)}if(path!=='/')return new Response('Not found',{status:404});const d=env.BUCKET?await read(env,'content')||DEFAULTS:DEFAULTS;return new Response(render(d),{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}})}catch{return json({error:'Unable to complete the request. Please try again.'},500)}}};
